// ============================================================
// Convierte la respuesta de OpenAQ v3 (results[]) en un item
// por estacion, con los campos que necesita la tabla `estaciones`.
// ============================================================
const body = $input.first().json;
const results = body.results || [];

if (results.length === 0) {
  throw new Error('OpenAQ no devolvio estaciones para iso=pe. Revisa la API key o el filtro.');
}

return results.map((loc) => ({
  json: {
    codigo_externo: String(loc.id),
    nombre: (loc.name || 'SIN NOMBRE').toUpperCase(),
    tipo: 'calidad_aire',
    zona: null,
    latitud: loc.coordinates ? loc.coordinates.latitude : null,
    longitud: loc.coordinates ? loc.coordinates.longitude : null,
    proveedor: 'OpenAQ',
  },
}));

// ============================================================
// El nombre del parametro NO viene en /latest (solo trae
// sensorsId). Hay que construir un mapa sensorId -> parametro
// a partir de la respuesta original de /locations, que es
// donde OpenAQ SI expone esa relacion (loc.sensors[]).
// ============================================================
const locsResponse = $('OpenAQ: listar estaciones PE').first().json;
const ubicaciones = locsResponse.results || [];

const sensorInfo = {};
for (const loc of ubicaciones) {
  const sensores = loc.sensors || [];
  for (const s of sensores) {
    sensorInfo[s.id] = {
      parametro: ((s.parameter && (s.parameter.name || s.parameter.id)) || 'desconocido').toLowerCase(),
      unidad: (s.parameter && s.parameter.units) || 'ug/m3',
    };
  }
}

const estaciones = $('Upsert estaciones').all();
const respuestas = $input.all();

const filas = [];

for (let i = 0; i < respuestas.length; i++) {
  const resp = respuestas[i].json;
  const estacionId = estaciones[i] ? estaciones[i].json.id : null;
  if (!estacionId) continue;

  const resultados = resp.results || [];
  for (const r of resultados) {
    const info = sensorInfo[r.sensorsId] || {};
    const parametro = info.parametro || 'desconocido';
    const valor = typeof r.value === 'number' ? r.value : null;
    const unidad = info.unidad || 'ug/m3';
    const medidoEn = (r.datetime && (r.datetime.utc || r.datetime.local)) || r.datetime || null;

    // Descarta si falta el valor, la fecha, o no se pudo mapear el parametro
    if (valor === null || !medidoEn || parametro === 'desconocido') continue;

    filas.push({
      json: {
        estacion_id: estacionId,
        parametro,
        valor,
        unidad,
        medido_en: medidoEn,
        payload_crudo: JSON.stringify(r),
      },
    });
  }
}

return filas;

// ============================================================
// Descarta lecturas de sensor evidentemente erroneas:
// negativas, o fuera de rango fisico razonable.
// ============================================================
const RANGOS = {
  pm25: [0, 1000], pm10: [0, 1500], no2: [0, 2000],
  so2: [0, 2000], o3: [0, 1000], co: [0, 50000],
};

return $input.all().filter((item) => {
  const { parametro, valor } = item.json;
  const rango = RANGOS[parametro];
  if (!rango) return true; // parametro no mapeado: se deja pasar, se revisa aparte
  return valor >= rango[0] && valor <= rango[1];
});
